targets.queryText:
SELECT generations AS "generations" FROM runs
WHERE batch_id = $batch AND target_length = $L AND charset_size = $k
  AND offspring = $n AND mutation_rate = $m AND reached_target = 1;

targets.rawQueryText:
SELECT generations AS "generations" FROM runs
WHERE batch_id = $batch AND target_length = $L AND charset_size = $k
  AND offspring = $n AND mutation_rate = $m AND reached_target = 1;

targets.queryText:
SELECT CAST(mutation_rate AS TEXT) AS "m", ROUND(AVG(regressions),2) AS "avg regressions"
FROM runs WHERE batch_id = $batch AND target_length = $L AND charset_size = $k AND offspring = $n
GROUP BY 1 ORDER BY CAST("m" AS REAL);

